// FUTURE-BACKEND: local routine summaries/replay payloads stay user-scoped and local in IMP-UX.02.
const routineHistoryLegacyStorageKey = "sbotics.imp-ux-02.routine-history.v1";
const routineHistoryStorageKey = `sbotics.imp-ux-02.routine-history.v1.${LOCAL_DEMO_USER_ID}`;
const routineHistoryLimit = 12;
const routineReplayStore = new RoutineReplayStore(LOCAL_DEMO_USER_ID);
const routineHistoryEventLimit = 800;
let routineHistoryStorageAvailable = true;
const routineHistoryText = (value, fallback = "") => String(value ?? fallback).slice(0, 160);
const routineHistoryNumber = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;

function normalizeStoredRoutineEvent(event) {
  if (!event || typeof event !== "object") return null;
  const textFields = ["tile", "source", "component", "reason", "rawType", "object", "message", "direction"];
  const normalized = {
    sequence: routineHistoryNumber(event.sequence),
    time: routineHistoryText(event.time),
    timeSeconds: routineHistoryNumber(event.timeSeconds),
    kind: routineHistoryText(event.kind, "runtime").replace(/[^a-z0-9-]/gi, "").slice(0, 48) || "runtime"
  };
  textFields.forEach((key) => {
    if (event[key] != null) normalized[key] = routineHistoryText(event[key]);
  });
  ["points", "multiplier", "attempt", "runAttempt", "path", "pathSegment", "pathTotal", "occurrence", "basePoints", "scale", "seconds", "skipped", "from", "to", "internalAttempts", "penaltyCapPoints", "speed", "totalPoints", "totalMultiplier"].forEach((key) => {
    if (event[key] != null) normalized[key] = routineHistoryNumber(event[key]);
  });
  ["checkpoint", "ramp"].forEach((key) => {
    if (event[key] != null) normalized[key] = event[key] === true;
  });
  if (Array.isArray(event.inputs)) {
    normalized.inputs = event.inputs.slice(0, 12).map((input) => ({
      component: routineHistoryText(input?.component),
      attempt: routineHistoryNumber(input?.attempt, 1),
      basePoints: routineHistoryNumber(input?.basePoints),
      scale: routineHistoryNumber(input?.scale, 1),
      points: routineHistoryNumber(input?.points),
      multiplier: routineHistoryNumber(input?.multiplier, 1)
    }));
  }
  return normalized;
}

function normalizeStoredRoutineScenario(value) {
  if (!value || typeof value !== "object") return null;
  const kit = value.starterKitSetup?.enabled === true || value.kit === true;
  const kitMount = kit ? normalizeStarterKitMount(value.starterKitSetup?.mount || value.kitMount) : null;
  return {
    schemaVersion: 1,
    arenaId: routineHistoryText(value.arenaId),
    arenaModel: value.arenaModel == null ? null : routineHistoryText(value.arenaModel),
    robotId: routineHistoryText(value.robotId),
    programId: routineHistoryText(value.programId),
    kit,
    starterKitSetup: { enabled: kit, ...(kitMount ? { mount: kitMount } : {}) },
    checkpoints: [...new Set((Array.isArray(value.checkpoints) ? value.checkpoints : []).slice(0, 100).map((id) => routineHistoryText(id)).filter(Boolean))],
    arenaSeed: routineHistoryText(value.arenaSeed),
    difficulty: Math.max(0, Math.min(4, Math.round(routineHistoryNumber(value.difficulty, 2)))),
    executionSeed: routineHistoryText(value.executionSeed),
    executionSeedExplicit: value.executionSeedExplicit === true || (value.executionSeedExplicit == null && Boolean(value.executionSeed))
  };
}

function normalizeStoredRoutineLog(log) {
  if (!log || typeof log !== "object" || !log.id) return null;
  const wasInterrupted = ["routineLogRunning", "routineLogPaused"].includes(log.status);
  const status = ["routineLogCompleted", "routineLogStopped", "routineLogInterrupted", "routineLogTimeLimitReached"].includes(log.status)
    ? log.status
    : "routineLogInterrupted";
  const events = (Array.isArray(log.events) ? log.events : []).slice(-routineHistoryEventLimit).map(normalizeStoredRoutineEvent).filter(Boolean);
  const internalAttempts = log.internalAttempts == null ? null : Math.max(0, Math.round(routineHistoryNumber(log.internalAttempts)));
  const lastSegmentEvent = [...events].reverse().find((event) => ["tile-enter", "tile-exit"].includes(event.kind) && event.attempt != null);
  const segmentAttempt = log.segmentAttempt != null
    ? Math.max(1, Math.round(routineHistoryNumber(log.segmentAttempt, 1)))
    : Math.max(1, Math.round(routineHistoryNumber(lastSegmentEvent?.attempt, log.attempt || 1)));
  const totalAttempts = log.totalAttempts != null
    ? Math.max(1, Math.round(routineHistoryNumber(log.totalAttempts, 1)))
    : internalAttempts != null ? internalAttempts + 1 : Math.max(1, Math.round(routineHistoryNumber(log.attempt, 1)));
  return {
    id: routineHistoryText(log.id),
    time: routineHistoryText(log.time, "—"),
    status: ["routineLogRunning", "routineLogPaused"].includes(log.status) ? "routineLogInterrupted" : status,
    attempt: Math.max(1, Math.round(routineHistoryNumber(log.attempt, 1))),
    segmentAttempt,
    totalAttempts,
    internalAttempts,
    path: Math.max(1, Math.round(routineHistoryNumber(log.path, 1))),
    pathTotal: Math.max(0, Math.round(routineHistoryNumber(log.pathTotal))),
    points: routineHistoryNumber(log.points),
    multiplier: routineHistoryNumber(log.multiplier, 1),
    duration: routineHistoryText(log.duration, "00:00"),
    durationSeconds: Math.max(0, routineHistoryNumber(log.durationSeconds)),
    robot: routineHistoryText(log.robot, "—"),
    arena: routineHistoryText(log.arena, "—"),
    program: routineHistoryText(log.program, "—"),
    seed: routineHistoryText(log.seed),
    mode: routineHistoryText(log.mode),
    replayStatus: wasInterrupted ? "expired" : ["available", "unavailable"].includes(log.replayStatus) ? log.replayStatus : "expired",
    replayQuality: ["full-12fps", "compact-6fps"].includes(log.replayQuality) ? log.replayQuality : "none",
    replayStorageWarning: log.replayStorageWarning === true,
    scenario: normalizeStoredRoutineScenario(log.scenario),
    captureGapCount: Math.max(0, Math.round(routineHistoryNumber(log.captureGapCount))),
    truncatedEventCount: Math.max(0, Math.round(routineHistoryNumber(log.truncatedEventCount))),
    events
  };
}

function readRoutineHistory() {
  try {
    const storage = globalThis.localStorage;
    if (!storage?.getItem) throw new Error("Routine history storage is unavailable");
    const raw = storage.getItem(routineHistoryStorageKey) || storage.getItem(routineHistoryLegacyStorageKey);
    if (!raw) return [];
    const saved = JSON.parse(raw);
    const history = Array.isArray(saved) ? saved.map(normalizeStoredRoutineLog).filter(Boolean).slice(0, routineHistoryLimit) : [];
    if (!storage.getItem(routineHistoryStorageKey)) {
      storage.setItem(routineHistoryStorageKey, JSON.stringify(history));
      try { storage.removeItem(routineHistoryLegacyStorageKey); } catch {}
    }
    return history;
  } catch {
    routineHistoryStorageAvailable = false;
    return [];
  }
}

function persistRoutineHistory() {
  try {
    const storage = globalThis.localStorage;
    if (!storage?.setItem) throw new Error("Routine history storage is unavailable");
    state.routineLogs = state.routineLogs.slice(0, routineHistoryLimit);
    storage.setItem(routineHistoryStorageKey, JSON.stringify(state.routineLogs));
    state.routineHistoryStorageAvailable = true;
    return true;
  } catch {
    state.routineHistoryStorageAvailable = false;
    return false;
  }
}

function upsertRoutineHistoryLog(log) {
  const previousIds = new Set(state.routineLogs.map((item) => item.id));
  state.routineLogs = [log, ...state.routineLogs.filter((item) => item.id !== log.id)].slice(0, routineHistoryLimit);
  const retainedIds = new Set(state.routineLogs.map((item) => item.id));
  previousIds.forEach((id) => { if (!retainedIds.has(id)) void routineReplayStore.deleteReplay(id).catch(() => {}); });
  return persistRoutineHistory();
}

function updateRoutineHistoryLog(log) {
  state.routineLogs = state.routineLogs.map((item) => item.id === log.id ? log : item);
  return persistRoutineHistory();
}

