  state.arenaGenerationTarget = target;
  state.arenaGenerationModel = null;
  state.arenaGenerationModelChoice = null;
  state.arenaGenerationModelOpen = false;
  state.arenaGenerationRescue = 1;
  state.arenaGenerationGenerateOnImport = target === "simulator";
  state.arenaGenerationRandomDifficulty = 2;
  state.arenaGenerationRandomSeed = "";
