function renderTeamActionDialog() {
  const deleting = state.teamAction === "delete";
  $("#team-action-title").textContent = t(deleting ? "teamDeleteConfirmTitle" : "teamLeaveConfirmTitle");
  $("#team-action-copy").textContent = t(deleting ? "teamDeleteConfirmCopy" : "teamLeaveConfirmCopy");
  $("#team-action-label").textContent = t(deleting ? "teamDeleteConfirmAction" : "teamLeaveConfirmAction");
  const icon = $("#team-action-icon");
  if (icon) icon.className = `ui-icon icon-${deleting ? "trash" : "sign-out"}`;
}

function openTeamActionDialog(action, invoker = null) {
  const teamId = invoker?.dataset.teamId;
  const team = state.teams.find((item) => item.id === teamId);
  if (!team) {
    showToast("toastTeamActionUnavailable");
    return;
  }
  if (action === "leave" && teamOwnerIsCurrentUser(team)) {
    showToast("teamOwnerCannotLeave");
    return;
  }
  if (!["leave", "delete"].includes(action)) return;
  state.teamAction = action;
  state.teamActionTeamId = teamId;
  state.teamActionInvoker = invoker || document.activeElement;
  renderTeamActionDialog();
  $("#team-action-dialog").hidden = false;
  $("#app-shell").inert = true;
  if (state.openPopup === "teams") $("#teams-popup").inert = true;
  requestAnimationFrame(() => $("#cancel-team-action")?.focus());
}

function closeTeamActionDialog({ restoreFocus = true } = {}) {
  const layer = $("#team-action-dialog");
  if (!layer) return;
  layer.hidden = true;
  $("#app-shell").inert = false;
  $("#teams-popup").inert = false;
  const invoker = state.teamActionInvoker;
  state.teamAction = null;
  state.teamActionTeamId = null;
  state.teamActionInvoker = null;
  if (restoreFocus && invoker?.isConnected) invoker.focus();
}

function confirmTeamAction() {
  const action = state.teamAction;
  const teamId = state.teamActionTeamId;
  const team = state.teams.find((item) => item.id === teamId);
  if (!team || !["leave", "delete"].includes(action)) {
    closeTeamActionDialog({ restoreFocus: false });
    showToast("toastTeamActionUnavailable");
    return;
  }
  if (action === "leave" && teamOwnerIsCurrentUser(team)) {
    closeTeamActionDialog({ restoreFocus: false });
    showToast("teamOwnerCannotLeave");
    return;
  }
  state.teams = state.teams.filter((item) => item.id !== teamId);
  state.eventEnrollments = state.eventEnrollments.filter((entry) => entry.teamId !== teamId);
  if (state.teamId === teamId) state.teamId = state.teams[0]?.id || null;
  state.teamNameError = "";
  closeTeamActionDialog({ restoreFocus: false });
  renderTopbar();
  renderSurfaceControls();
  if (state.section === "events") renderEventsPage();
  if (state.openPopup === "teams") renderTeamsPopup();
  showToast(action === "delete" ? "toastTeamDeleted" : "toastTeamLeft");
}

function openEventAdminRemoveTeamDialog(invoker = null) {
  const teamId = invoker?.dataset.eventAdminTeamId;
  if (!teamId || !state.eventAdminTeamRoster.some((team) => team.id === teamId)) return;
  state.eventAdminRemoveTeamId = teamId;
  state.eventAdminRemoveTeamInvoker = invoker || document.activeElement;
  $("#event-admin-remove-team-dialog").hidden = false;
  $("#app-shell").inert = true;
  requestAnimationFrame(() => $("#event-admin-remove-team-dialog [data-action='cancel-event-admin-remove-team']")?.focus());
}

function closeEventAdminRemoveTeamDialog({ restoreFocus = true } = {}) {
  const dialog = $("#event-admin-remove-team-dialog");
  if (!dialog) return;
  dialog.hidden = true;
  $("#app-shell").inert = false;
  const invoker = state.eventAdminRemoveTeamInvoker;
  state.eventAdminRemoveTeamId = null;
  state.eventAdminRemoveTeamInvoker = null;
  if (restoreFocus && invoker?.isConnected) invoker.focus();
}

function confirmEventAdminRemoveTeam() {
  if (!state.eventAdminDraft) {
    closeEventAdminRemoveTeamDialog({ restoreFocus: false });
    return;
  }
  syncEventAdminDraftFromDom();
  const teamIndex = state.eventAdminTeamRoster.findIndex((team) => team.id === state.eventAdminRemoveTeamId);
  if (teamIndex < 0) {
    closeEventAdminRemoveTeamDialog({ restoreFocus: false });
    return;
  }
  const [removedTeam] = state.eventAdminTeamRoster.splice(teamIndex, 1);
  delete state.eventAdminTeamMemberDrafts[removedTeam.id];
  state.eventAdminTeamError = "";
  state.eventAdminTeamCsvStatus = "";
  state.eventAdminDirty = true;
  closeEventAdminRemoveTeamDialog({ restoreFocus: false });
  renderEventsPage();
  showToast("toastEventAdminTeamRemoved");
}

function confirmEventWithdrawal() {
  const eventId = state.eventWithdrawEventId;
  const record = eventsCatalog.find((event) => event.id === eventId);
  if (!record?.enrollmentOpen || state.competitionActive) {
    closeEventWithdrawDialog({ restoreFocus: false });
    showToast("toastEventWithdrawUnavailable");
    return;
  }
  state.eventEnrollments = state.eventEnrollments.filter((entry) => entry.eventId !== eventId);
  if (state.eventSelectedId === eventId) {
    state.eventSelectedId = "obr";
    state.eventRoundId = null;
  }
  state.eventFlow = "joined";
  closeEventWithdrawDialog({ restoreFocus: false });
  renderTopbar();
  renderSurfaceControls();
  renderEventsPage();
  showToast("toastEventWithdrawn");
}

