function eventImageMarkup(className = "event-image", alt = "") {
  const image = state.eventImage;
  return image?.url
    ? `<img class="${className}" src="${escapeHtml(image.url)}" alt="${escapeHtml(alt)}" />`
    : `<span class="${className} event-image-placeholder" role="img" aria-label="${escapeHtml(t("eventsCompetitionImagePlaceholder"))}"><strong>1:1</strong><small>${t("eventsCompetitionImagePlaceholder")}</small></span>`;
}

function teamAvatarMarkup(team, className = "team-avatar") {
  if (!team) return "";
  const initial = team.avatar === "initial";
  const value = initial ? teamInitials(team) : team.avatar;
  return `<span class="avatar ${className}${initial ? "" : " is-emoji"}" style="background:${normalizeProfileColor(team.background)};--avatar-zoom:${normalizeProfileAvatarSize(team.avatarSize)}" aria-hidden="true"><span class="avatar-content">${escapeHtml(value)}</span></span>`;
}

const eventInvitationTeam = { avatar: "🌳", background: "#50c878", avatarSize: 1 };

const teamMemberProfiles = {
  teamMemberOne: { avatar: "initial", initials: "L", background: "#2fa9c2", avatarSize: 1 },
  teamMemberTwo: { avatar: "🐱", initials: "", background: "#5c8fd8", avatarSize: 1 },
  teamMemberThree: { avatar: "🦊", initials: "", background: "#ed9a52", avatarSize: 1 }
};

function teamMemberAvatarMarkup(memberKey) {
  const profile = memberKey === "teamMemberYou"
    ? { avatar: state.profileAvatar, initials: DEMO_PROFILE_INITIALS, background: state.profileBackground, avatarSize: state.profileAvatarSize }
    : teamMemberProfiles[memberKey] || { avatar: "initial", initials: "?", background: "#66717a", avatarSize: 1 };
  const initial = profile.avatar === "initial";
  const value = initial ? profile.initials : profile.avatar;
  return `<span class="avatar team-member-avatar${initial ? "" : " is-emoji"}" style="background:${normalizeProfileColor(profile.background)};--avatar-zoom:${normalizeProfileAvatarSize(profile.avatarSize)}" aria-hidden="true"><span class="avatar-content">${escapeHtml(value)}</span></span>`;
}

function teamMemberRowMarkup(team, memberKey) {
  const isOwner = team?.ownerKey === memberKey;
  const ownerLabel = t("teamOwner");
  const ownerMarkup = isOwner ? `<span class="team-owner-mark" role="img" aria-label="${escapeHtml(ownerLabel)}" title="${escapeHtml(ownerLabel)}"><span class="ui-icon icon-owner" aria-hidden="true"></span></span>` : "";
  return `<li>${teamMemberAvatarMarkup(memberKey)}<span>${escapeHtml(t(memberKey))}</span>${ownerMarkup}</li>`;
}

function teamOwnerIsCurrentUser(team) {
  return team?.ownerKey === "teamMemberYou";
}

function teamMembershipActions(team) {
  if (!team) return "";
  const owner = teamOwnerIsCurrentUser(team);
  const action = owner ? "team-delete" : "team-leave";
  const icon = owner ? "trash" : "sign-out";
  const label = owner ? t("teamDelete") : t("teamLeave");
  return `<div class="team-members-actions"><button class="secondary-button action-button${owner ? " is-danger" : ""}" type="button" data-action="${action}" data-team-id="${escapeHtml(team.id)}"><span class="ui-icon icon-${icon}" aria-hidden="true"></span><span>${label}</span></button></div>`;
}

function eventParticipantRobotOptions() {
  return [
    { id: "best", resourceId: "bruna", snapshotId: "bruna@01", labelKey: "eventsRobotOptionBest", ownerKey: "teamMemberThree", modifiedKey: "resourceModifiedTwoDays", source: "participant" },
    { id: "mine", resourceId: "trekker", snapshotId: "trekker@04", labelKey: "eventsRobotOptionMine", ownerKey: "teamMemberOne", modifiedKey: "resourceModifiedNow", source: "participant" },
    { id: "other", resourceId: "obsidian", snapshotId: "obsidian@01", labelKey: "robotObsidian", ownerKey: "teamMemberTwo", modifiedKey: "resourceModifiedYesterday", source: "participant" }
  ];
}

function eventRobotOptions(round = selectedEventRound()) {
  if (eventRoundProvides(round, "robot")) {
    return eventRoundSelectedResourceOptions(round, "robot").map((option) => {
      const snapshotId = option.snapshotId || option.id || "";
      const resourceId = option.resourceId || String(snapshotId).split("@")[0];
      const resource = robotCatalog.find((item) => item.id === resourceId);
      return {
        ...option,
        id: option.id || resourceId || snapshotId,
        resourceId,
        snapshotId,
        name: option.name || (resource ? robotName(resource) : resourceId),
        nameKey: option.nameKey || resource?.nameKey,
        ownerKey: option.ownerKey || "",
        modifiedKey: option.modifiedKey || resource?.modifiedKey,
        source: "round"
      };
    });
  }
  return eventParticipantRobotOptions();
}

function eventArenaOptions(round = selectedEventRound()) {
  if (eventRoundProvides(round, "arena")) {
    return eventRoundSelectedResourceOptions(round, "arena").map((option) => {
      const arena = arenaById(option.id || option.arenaId);
      const name = eventAdminArenaOptionName(option);
      return {
        ...option,
        id: option.id || option.arenaId,
        name,
        meta: `${t("eventsRoundResourceProvided")} · ${t("eventsResourceSnapshot")} ${option.snapshotId || "—"}`,
        search: `${name} ${t("eventsRoundResourceProvided")} ${option.snapshotId || ""}`,
        previewKind: "arena",
        source: "round",
        modifiedKey: option.modifiedKey || arena?.modifiedKey
      };
    });
  }
  return arenaCatalog().map((arena) => {
    const name = arenaName(arena);
    return {
      id: arena.id,
      name,
      meta: `${t("eventsRoundResourceParticipant")} · ${t(arena.detailKey)}`,
      search: `${arena.id} ${name} ${t(arena.detailKey)} ${t("eventsRoundResourceParticipant")}`,
      previewKind: "arena",
      source: "participant",
      modifiedKey: arena.modifiedKey
    };
  });
}

function eventParticipantProgramOptions() {
  const ownerKeys = ["teamMemberOne", "teamMemberTwo", "teamMemberThree"];
  return programCatalog
    .filter((program) => program.language === "javascript")
    .map((program, index) => ({ program, ownerKey: ownerKeys[index] || "teamMemberOne", source: "participant", selectionId: program.id }));
}

function eventProgramOptions(round = selectedEventRound()) {
  if (eventRoundProvides(round, "program")) {
    return eventRoundSelectedResourceOptions(round, "program")
      .map((option) => {
        const programId = option.programId || option.resourceId || option.id;
        const program = programCatalog.find((item) => item.id === programId && item.language === "javascript");
        if (!program) return null;
        return { program, ownerKey: "", source: "round", selectionId: option.id || program.id, snapshotId: option.snapshotId || `program:${program.id}@01` };
      })
      .filter(Boolean);
  }
  return eventParticipantProgramOptions();
}

function selectedEventRobot(round = selectedEventRound()) {
  const options = eventRobotOptions(round);
  return options.find((robot) => robot.id === state.eventRobotId) || options[0] || null;
}

function eventRobotDisplayName(robot = selectedEventRobot()) {
  if (!robot) return t("eventsRoundResourceEmpty");
  const name = robot.name || (robot.nameKey ? t(robot.nameKey) : robot.labelKey ? t(robot.labelKey) : robot.id);
  return robot.ownerKey ? `${name} (${t(robot.ownerKey)})` : name;
}

function eventProgramDisplayName(option) {
  if (!option?.program) return t("eventsRoundResourceEmpty");
  const name = programName(option.program);
  return option.ownerKey ? `${name} (${t(option.ownerKey)})` : name;
}

function normalizeEventRoundSelections(round = selectedEventRound()) {
  const arenas = eventArenaOptions(round);
  const robots = eventRobotOptions(round);
  const programs = eventProgramOptions(round);
  if (!arenas.some((entry) => entry.id === state.eventArenaId)) state.eventArenaId = arenas[0]?.id || "";
  if (!robots.some((entry) => entry.id === state.eventRobotId)) state.eventRobotId = robots[0]?.id || "";
  if (!programs.some((entry) => (entry.selectionId || entry.program?.id) === state.eventProgramId)) state.eventProgramId = programs[0]?.selectionId || programs[0]?.program?.id || "";
  return { arenas, robots, programs };
}

function renderEventUtilityPanel() {
  if (!state.eventUtility) return "";
  const utility = {
    notifications: { icon: "bell", titleKey: "eventNotificationsTitle", copyKey: "eventNotificationsCopy", body: `<ul class="event-utility-list"><li>${teamAvatarMarkup(eventInvitationTeam, "team-avatar event-notification-avatar")}<span><strong>${t("eventInvitation")}</strong><small>${t("eventInvitationCopy")}</small></span><button class="secondary-button action-button" type="button" data-action="event-accept-invite"><span class="ui-icon icon-check" aria-hidden="true"></span><span>${t("eventAccept")}</span></button></li><li><span class="ui-icon icon-calendar" aria-hidden="true"></span><span><strong>${t("eventRoundPublished")}</strong><small>${t("eventRoundPublishedCopy")}</small></span></li></ul>` },
    contests: { icon: "warning", titleKey: "eventContestsTitle", copyKey: "eventContestsCopy", body: `<div class="event-utility-empty"><span class="ui-icon icon-check" aria-hidden="true"></span><strong>${t("eventPostFlightNoCase")}</strong><small>${t("eventReviewCopy")}</small></div>` },
    rounds: { icon: "calendar", titleKey: "eventRoundsUtilityTitle", copyKey: "eventRoundsUtilityCopy", body: `<ul class="event-utility-list"><li><span class="ui-icon icon-broadcast" aria-hidden="true"></span><span><strong>${t("eventTitle")} · ${t("eventRoundTitle")}</strong><small>${t("eventsRoundStatusOpen")}</small></span><button class="primary-button action-button" type="button" data-action="event-open-round"><span class="ui-icon icon-play" aria-hidden="true"></span><span>${t("eventsRoundParticipate")}</span></button></li><li><span class="ui-icon icon-calendar" aria-hidden="true"></span><span><strong>${t("eventsMineTwo")}</strong><small>${t("eventsRoundUpcoming")}</small></span></li></ul>` }
  }[state.eventUtility];
  if (!utility) return "";
  return `<section class="event-utility-panel event-card" aria-labelledby="event-utility-title"><div class="event-card-heading"><div><p class="eyebrow">${t("eventsPageKicker")}</p><h3 id="event-utility-title">${t(utility.titleKey)}</h3></div><button class="text-button" type="button" data-action="close-event-utility"><span class="ui-icon icon-close" aria-hidden="true"></span><span>${t("closeButton")}</span></button></div><p>${t(utility.copyKey)}</p>${utility.body}</section>`;
}

function renderEventHero({ joined = false } = {}) {
  return `<section class="event-hero event-card" aria-labelledby="event-feature-title"><div class="event-hero-image-wrap">${eventImageMarkup("event-image", t("eventsCompetitionImage"))}<button class="text-button event-image-edit" type="button" data-action="open-event-image"><span class="ui-icon icon-file" aria-hidden="true"></span><span>${t("eventsCompetitionImageEdit")}</span></button></div><div class="event-hero-body"><div class="event-card-header"><div><span class="event-card-kicker is-live"><span class="ui-icon icon-broadcast" aria-hidden="true"></span>${t("eventRegistrationLabel")}</span><h3 id="event-feature-title">${t("eventTitle")}</h3><p>${t("eventSubtitle")}</p></div><span class="event-card-phase"><strong>${t("eventPhase")}</strong><span>${t("eventRoundTitle")}</span></span></div><div class="event-meta-grid"><div><span>${t("eventJoinWindow")}</span><strong>${t("eventJoinWindowValue")}</strong></div><div><span>${t("eventRoundCount")}</span><strong>${t("eventRoundCountValue")}</strong></div><div><span>${t("eventsQueueSummary")}</span><strong>${t("eventsProgressLabel")}</strong></div></div><div class="event-card-actions"><button class="secondary-button action-button" type="button" data-action="event-view-details" data-event-id="obr"><span class="ui-icon icon-eye" aria-hidden="true"></span><span>${t("eventViewDetails")}</span></button>${joined ? `<button class="primary-button action-button" type="button" data-action="event-open-round" data-event-id="obr"><span class="ui-icon icon-play" aria-hidden="true"></span><span>${t("eventsRoundParticipate")}</span></button>` : `<button class="primary-button action-button" type="button" data-action="event-join" data-event-id="obr"><span class="ui-icon icon-add" aria-hidden="true"></span><span>${t("eventJoin")}</span></button>`}</div><p class="event-readonly"><span class="ui-icon icon-info" aria-hidden="true"></span>${t("eventDetailsCopy")}</p></div></section>`;
}

function renderTeamIdentityForm(team, { inline = teamEditorIsInline() } = {}) {
  if (!team) return "";
  const config = teamEditorConfig(inline);
  const colors = ["#2fa9c2", "#5c8fd8", "#9b6bb5", "#50c878", "#ed9a52", "#f06a78"].map((color) => `<button class="team-color-option${normalizeProfileColor(team.background) === color ? " is-selected" : ""}" type="button" data-action="team-select-color" data-color="${color}" aria-label="${escapeHtml(color)}" aria-pressed="${normalizeProfileColor(team.background) === color}"><span style="--swatch:${color}"></span></button>`).join("");
  const avatar = team.avatar === "initial" ? teamInitials(team) : team.avatar || "";
  const formClass = inline ? "team-identity-form-inline" : "team-identity-form-popup";
  return `<div class="popup-section ${formClass}"><div class="section-heading"><h3>${t("teamIdentityTitle")}</h3><span class="ui-icon icon-file" aria-hidden="true"></span></div><label class="field-row team-name-field"><span>${t("teamNameLabel")}</span><input id="${config.name}" type="text" value="${escapeHtml(teamDisplayName(team))}" placeholder="${escapeHtml(t("teamNamePlaceholder"))}" maxlength="80" aria-invalid="${Boolean(state.teamNameError)}" /></label>${state.teamNameError ? `<p class="tile-image-error" role="alert"><span class="ui-icon icon-warning" aria-hidden="true"></span>${escapeHtml(state.teamNameError)}</p>` : ""}<div class="team-avatar-field"><span class="team-avatar-field-label">${t("teamAvatarLabel")}</span><button class="profile-emoji-trigger team-emoji-trigger" id="${config.trigger}" type="button" data-action="open-team-identity" aria-haspopup="dialog" aria-expanded="${state.teamEmojiPickerOpen}" aria-controls="${config.picker}"><span class="profile-emoji-trigger-value" aria-hidden="true">${escapeHtml(avatar)}</span><span>${team.avatar === "initial" ? t("teamAvatarButton") : t("teamAvatarChange")}</span><span class="ui-icon icon-chevron-down" aria-hidden="true"></span></button></div>${renderTeamEmojiPickerMarkup(config)}<div class="profile-size-row"><label for="${config.size}">${t("teamAvatarSize")}</label><div class="profile-size-control"><input id="${config.size}" type="range" min="0.75" max="2" step="0.05" value="${normalizeProfileAvatarSize(team.avatarSize)}" aria-label="${escapeHtml(t("teamAvatarSize"))}" /><output for="${config.size}">${Math.round(normalizeProfileAvatarSize(team.avatarSize) * 100)}%</output></div></div><div class="profile-color-row"><span class="profile-color-label">${t("teamBackgroundLabel")}</span><div class="profile-color-controls"><div class="team-color-options" role="radiogroup" aria-label="${escapeHtml(t("teamBackgroundLabel"))}">${colors}</div><label class="profile-color-custom"><span>${t("teamBackgroundCustom")}</span><input id="${config.background}" type="color" value="${normalizeProfileColor(team.background)}" aria-label="${escapeHtml(t("teamBackgroundCustom"))}" /></label></div></div><button class="primary-button action-button wide-button" type="button" data-action="save-team"><span class="ui-icon icon-save" aria-hidden="true"></span><span>${t("teamNameSave")}</span></button></div>`;
}

function renderTeamManagementView() {
  const team = selectedTeam();
  const heading = `<div class="events-section-heading"><div><p class="eyebrow">${t("eventsModeTeams")}</p><h3>${t("teamListTitle")}</h3><p>${t("eventsModeTeamsCopy")}</p></div><button class="primary-button action-button" type="button" data-action="create-team"><span class="ui-icon icon-add" aria-hidden="true"></span><span>${t("profileCreateTeam")}</span></button></div>`;
  if (!state.teams.length) return `${heading}<section class="event-card team-empty-card"><div class="event-view-empty"><p>${t("teamNoTeams")}</p></div></section>`;
  const teamList = state.teams.map((item) => `<button class="team-list-item${item.id === team?.id ? " is-selected" : ""}" type="button" data-action="select-team" data-team-id="${escapeHtml(item.id)}" aria-pressed="${item.id === team?.id}">${teamAvatarMarkup(item)}<span><strong>${escapeHtml(teamDisplayName(item))}</strong><small>${item.members}/${item.maxMembers} ${t("eventsTeamMembers")} · ${t(item.statusKey || "teamStatusActive")}</small></span><span class="ui-icon icon-chevron-right" aria-hidden="true"></span></button>`).join("");
  const detail = `<section class="event-card team-detail-card" data-team-editor="inline"><div class="team-detail-heading">${teamAvatarMarkup(team, "team-avatar team-avatar-large team-editor-avatar")}<div><p class="eyebrow">${t(team.roleKey || "teamRoleMember")}</p><h3>${escapeHtml(teamDisplayName(team))}</h3><p>${team.members}/${team.maxMembers} ${t("eventsTeamMembers")}</p></div></div>${renderTeamIdentityForm(team, { inline: true })}<div class="team-members-preview"><div class="section-heading"><h3>${t("teamMembersTitle")}</h3><span class="ui-icon icon-person" aria-hidden="true"></span></div><ul>${(team.memberKeys || []).map((key) => teamMemberRowMarkup(team, key)).join("")}</ul><div class="event-card-actions"><button class="secondary-button action-button" type="button" data-action="team-invite"><span class="ui-icon icon-add" aria-hidden="true"></span><span>${t("teamInvite")}</span></button></div>${teamMembershipActions(team)}</div></section>`;
  return `${heading}<div class="events-team-layout"><section class="event-card team-list-card"><div class="event-card-heading"><h3>${t("teamListTitle")}</h3><span class="ui-icon icon-person" aria-hidden="true"></span></div><div class="team-list">${teamList}</div></section>${detail}</div>`;
}

function renderParticipationSetupLegacy() {
  const round = selectedEventRound();
  const record = selectedEventRecord();
  const team = selectedTeam();
  const selectedRobot = selectedEventRobot();
  const programs = eventProgramOptions();
  const selectedProgram = programs.find(({ program }) => program.id === state.eventProgramId) || programs[0];
  const ready = Boolean(team && state.eventRobotId && state.eventProgramId && state.eventArenaId);
  return `<section class="event-setup-card event-card" aria-labelledby="event-setup-title"><div class="event-setup-back"><button class="text-button" type="button" data-action="event-setup-back"><span class="ui-icon icon-chevron-left" aria-hidden="true"></span><span>${t("eventsSetupBack")}</span></button></div><div class="event-card-header"><div><span class="event-card-kicker"><span class="ui-icon icon-settings" aria-hidden="true"></span>${t("eventsRoundSetup")}</span><h3 id="event-setup-title">${t("eventsParticipationSetupTitle")}</h3><p>${t("eventsParticipationSetupCopy")}</p></div><span class="event-card-phase"><strong>${round ? t(round.statusKey) : t("eventPhase")}</strong><span>${round ? t(round.windowKey) : t("eventsRoundOpen")}</span></span></div><div class="event-setup-grid"><div class="event-setup-block event-setup-team-block"><div class="section-heading"><h4>${t("eventsChooseTeam")}</h4><span class="ui-icon icon-person" aria-hidden="true"></span></div><button class="event-selection-card" type="button" data-action="open-teams">${teamAvatarMarkup(team)}<span><strong>${escapeHtml(teamDisplayName(team))}</strong><small>${team?.members || 0}/${team?.maxMembers || 4} ${t("eventsTeamMembers")} · ${t("eventsTeamReady")}</small></span><span class="ui-icon icon-chevron-right" aria-hidden="true"></span></button></div><div class="event-setup-block event-setup-robot-block"><div class="section-heading"><h4>${t("eventsSelectRobot")}</h4><span class="ui-icon icon-robot" aria-hidden="true"></span></div>${resourcePickerMarkup("event-robot", "robot", t("eventsSelectRobot"), t("eventsSelectRobot"), "", false, "event")}</div><div class="event-setup-block event-setup-program-block"><div class="section-heading"><h4>${t("eventsSelectProgram")}</h4><span class="ui-icon icon-code" aria-hidden="true"></span></div>${resourcePickerMarkup("event-program-select", "program", t("eventsSelectProgram"), t("eventsSelectProgram"), "", false, "event")}</div><div class="event-setup-block event-setup-arena-block"><div class="section-heading"><h4>${t("eventsSelectArena")}</h4><span class="ui-icon icon-arena" aria-hidden="true"></span></div><div class="event-readonly-row"><span class="ui-icon icon-lock" aria-hidden="true"></span><span><strong>${t("eventsResourceArena")}</strong><small>${escapeHtml(`${t(record.titleKey)} · ${eventRoundDisplayName(round)}`)}</small></span></div></div></div><div class="event-exact-combination"><span class="ui-icon icon-check" aria-hidden="true"></span><span><strong>${t("eventResourcesTitle")}</strong><small>${eventRobotDisplayName(selectedRobot)} · ${escapeHtml(eventProgramDisplayName(selectedProgram))} · ${t("eventsResourceArena")}</small></span></div><label class="event-acknowledgement"><input id="event-acknowledgement" type="checkbox"${state.eventAcknowledged ? " checked" : ""} /><span><strong>${t("eventAcknowledgement")}</strong><small>${t("eventAcknowledgementCopy")}</small></span></label><div class="event-setup-footer"><span class="event-action-lock"><span class="ui-icon icon-${state.eventAcknowledged ? "check" : "lock"}" aria-hidden="true"></span><span>${state.eventAcknowledged ? t("eventStart") : t("eventStartLockedCopy")}</span></span><button class="primary-button action-button" type="button" data-action="event-start"${ready && state.eventAcknowledged ? "" : " disabled"}><span class="ui-icon icon-play" aria-hidden="true"></span><span>${state.eventAcknowledged ? t("eventStart") : t("eventStartLocked")}</span></button></div></section>`;
}

function renderParticipationSetup() {
  const round = selectedEventRound();
  const record = selectedEventRecord();
  const team = selectedTeam();
  const { arenas, robots, programs } = normalizeEventRoundSelections(round);
  const selectedArena = arenas.find((entry) => entry.id === state.eventArenaId) || arenas[0];
  const selectedRobot = robots.find((entry) => entry.id === state.eventRobotId) || robots[0];
  const selectedProgram = programs.find((entry) => (entry.selectionId || entry.program?.id) === state.eventProgramId) || programs[0];
  const sourceNote = (kind) => `<small class="event-resource-source">${t(eventRoundProvides(round, kind) ? "eventsRoundResourceProvided" : "eventsRoundResourceParticipant")}</small>`;
  const arenaName = selectedArena?.name || t("eventsRoundResourceEmpty");
  const robotNameLabel = selectedRobot ? eventRobotDisplayName(selectedRobot) : t("eventsRoundResourceEmpty");
  const programNameLabel = selectedProgram ? eventProgramDisplayName(selectedProgram) : t("eventsRoundResourceEmpty");
  const ready = Boolean(team && selectedArena && selectedRobot && selectedProgram);
  return `<section class="event-setup-card event-card" aria-labelledby="event-setup-title"><div class="event-setup-back"><button class="text-button" type="button" data-action="event-setup-back"><span class="ui-icon icon-chevron-left" aria-hidden="true"></span><span>${t("eventsSetupBack")}</span></button></div><div class="event-card-header"><div><span class="event-card-kicker"><span class="ui-icon icon-settings" aria-hidden="true"></span>${t("eventsRoundSetup")}</span><h3 id="event-setup-title">${t("eventsParticipationSetupTitle")}</h3><p>${t("eventsParticipationSetupCopy")}</p></div><span class="event-card-phase"><strong>${round ? t(round.statusKey) : t("eventPhase")}</strong><span>${round ? t(round.windowKey) : t("eventsRoundOpen")}</span></span></div><div class="event-setup-grid"><div class="event-setup-block event-setup-team-block"><div class="section-heading"><h4>${t("eventsChooseTeam")}</h4><span class="ui-icon icon-person" aria-hidden="true"></span></div><button class="event-selection-card" type="button" data-action="open-teams">${teamAvatarMarkup(team)}<span><strong>${escapeHtml(teamDisplayName(team))}</strong><small>${team?.members || 0}/${team?.maxMembers || 4} ${t("eventsTeamMembers")} · ${t("eventsTeamReady")}</small></span><span class="ui-icon icon-chevron-right" aria-hidden="true"></span></button></div><div class="event-setup-block event-setup-arena-block"><div class="section-heading"><h4>${t("eventsSelectArena")}</h4><span class="ui-icon icon-arena" aria-hidden="true"></span></div>${sourceNote("arena")}${resourcePickerMarkup("event-arena-select", "arena", t("eventsSelectArena"), t("eventsSelectArena"), "", false, "event")}</div><div class="event-setup-block event-setup-robot-block"><div class="section-heading"><h4>${t("eventsSelectRobot")}</h4><span class="ui-icon icon-robot" aria-hidden="true"></span></div>${sourceNote("robot")}${resourcePickerMarkup("event-robot", "robot", t("eventsSelectRobot"), t("eventsSelectRobot"), "", false, "event")}</div><div class="event-setup-block event-setup-program-block"><div class="section-heading"><h4>${t("eventsSelectProgram")}</h4><span class="ui-icon icon-code" aria-hidden="true"></span></div>${sourceNote("program")}${resourcePickerMarkup("event-program-select", "program", t("eventsSelectProgram"), t("eventsSelectProgram"), "", false, "event")}</div></div><div class="event-exact-combination"><span class="ui-icon icon-check" aria-hidden="true"></span><span><strong>${t("eventResourcesTitle")}</strong><small>${escapeHtml(`${arenaName} · ${robotNameLabel} · ${programNameLabel}`)}</small></span></div><label class="event-acknowledgement"><input id="event-acknowledgement" type="checkbox"${state.eventAcknowledged ? " checked" : ""} /><span><strong>${t("eventAcknowledgement")}</strong><small>${t("eventAcknowledgementCopy")}</small></span></label><div class="event-setup-footer"><span class="event-action-lock"><span class="ui-icon icon-${state.eventAcknowledged ? "check" : "lock"}" aria-hidden="true"></span><span>${state.eventAcknowledged ? t("eventStart") : t("eventStartLockedCopy")}</span></span><button class="primary-button action-button" type="button" data-action="event-start"${ready && state.eventAcknowledged ? "" : " disabled"}><span class="ui-icon icon-play" aria-hidden="true"></span><span>${state.eventAcknowledged ? t("eventStart") : t("eventStartLocked")}</span></button></div></section>`;
}

function renderRoundGroup({ titleKey, icon, className, body }) {
  return `<section class="event-round-group ${className || ""}" aria-labelledby="${className}-title"><div class="event-section-heading"><div><h3 id="${className}-title">${t(titleKey)}</h3></div><span class="ui-icon icon-${icon}" aria-hidden="true"></span></div>${body}</section>`;
}

function eventHistoryReportLogText(record) {
  return (record?.report?.log || []).map(([time, key]) => `[${time}] ${t(key)} · ${t(record.titleKey)}`).join("\n");
}

function eventHistoryReportLogActions(record) {
  const copyLabel = state.eventHistoryCopyStatus === "copied" ? t("eventsHistoryReportLogCopied") : t("eventsHistoryReportCopyLog");
  return `<button class="secondary-button action-button" type="button" data-action="event-history-copy-log" data-event-history-report-id="${escapeHtml(record.id)}"><span class="ui-icon icon-copy" aria-hidden="true"></span><span>${copyLabel}</span></button>`;
}

function renderEventPostFlightReport() {
  const record = eventHistoryRecords()[0];
  const team = state.teams.find((item) => item.id === record.teamId) || selectedTeam();
  const report = record.report;
  const log = report.log.map(([time, key]) => `<li><time>${time}</time><span><strong>${t(key)}</strong><small>${t(record.titleKey)}</small></span></li>`).join("");
  return `<section class="event-postflight-detail-view" aria-labelledby="event-postflight-report-title"><div class="event-postflight-detail-heading"><div><h3 id="event-postflight-report-title">${t("eventsHistoryReportTitle")}</h3><p>${t("eventPostFlightReportCopy")}</p></div><span class="ui-icon icon-file" aria-hidden="true"></span></div><div class="event-history-report-identity">${teamAvatarMarkup(team, "team-avatar event-history-report-avatar")}<div><strong>${t(record.titleKey)}</strong><small>${t(record.metaKey)}</small></div></div><div class="event-history-report-metrics"><div><span>${t("eventsHistoryReportScore")}</span><strong>${t(report.scoreKey)}</strong></div><div><span>${t("eventsHistoryReportDuration")}</span><strong>${t(report.durationKey)}</strong></div><div><span>${t("eventsHistoryReportRobot")}</span><strong>${escapeHtml(report.robot)}</strong></div><div><span>${t("eventsHistoryReportProgram")}</span><strong>${t(report.programKey)}</strong></div></div><div class="event-postflight-log"><div class="event-card-heading"><div><h4>${t("eventsHistoryReportLogTitle")}</h4><p>${t("eventsHistoryReportLogCopy")}</p></div><span class="ui-icon icon-route" aria-hidden="true"></span></div><ol class="event-history-log">${log}</ol><div class="event-card-actions">${eventHistoryReportLogActions(record)}</div></div></section>`;
}

function renderEventPostFlightReplay() {
  const record = selectedEventRecord();
  const progress = Math.max(0, Math.min(100, Number(state.eventReplayPosition) || 0));
  return `<section class="event-postflight-detail-view" aria-labelledby="event-postflight-replay-title"><div class="event-postflight-detail-heading"><div><h3 id="event-postflight-replay-title">${t("eventReplayTitle")}</h3><p>${t("eventPostFlightReplayCopy")}</p></div><span class="ui-icon icon-history" aria-hidden="true"></span></div><div class="event-replay-stage event-postflight-replay-stage" aria-label="${escapeHtml(t("eventReplayTitle"))}"><div class="event-replay-grid" aria-hidden="true"></div><div class="event-replay-line" aria-hidden="true"></div><span class="event-replay-robot" style="left:${progress}%" aria-hidden="true"><span class="ui-icon icon-robot"></span></span><span class="event-replay-scene-label">${t(record.titleKey)} · ${eventRoundDisplayName()}</span></div><div class="event-replay-control"><label for="event-replay-position">${t("eventReplayProgress")}</label><output id="event-replay-progress-value" for="event-replay-position">${progress}%</output><input id="event-replay-position" type="range" min="0" max="100" value="${progress}" aria-label="${escapeHtml(t("eventReplayProgress"))}" /></div></section>`;
}

function renderPostFlight() {
  const canceled = state.eventFlow === "canceled";
  const view = ["summary", "report", "replay"].includes(state.eventPostFlightView) ? state.eventPostFlightView : "summary";
  let detail = "";
  if (view === "report") {
    detail = renderEventPostFlightReport();
  } else if (view === "replay") {
    detail = renderEventPostFlightReplay();
  } else {
    detail = `<div class="event-postflight-grid"><article class="event-postflight-panel"><div class="section-heading"><h4>${t("eventsRoundReport")}</h4><span class="ui-icon icon-file" aria-hidden="true"></span></div><p>${t("eventReportCopy")}</p><div class="event-replay-preview"><span class="ui-icon icon-file" aria-hidden="true"></span><span><strong>${t("eventReportSummary")}</strong><small>${t("eventReviewCopy")}</small></span></div><button class="secondary-button action-button" type="button" data-action="event-postflight-report"><span class="ui-icon icon-open" aria-hidden="true"></span><span>${t("eventsRoundReport")}</span></button></article><article class="event-postflight-panel"><div class="section-heading"><h4>${t("eventsRoundReplay")}</h4><span class="ui-icon icon-history" aria-hidden="true"></span></div><p>${t("eventPostFlightReplayCopy")}</p><div class="event-replay-preview"><span class="ui-icon icon-play" aria-hidden="true"></span><span><strong>${t("eventTitle")} · ${eventRoundDisplayName()}</strong><small>${t("eventsRoundReplay")} · ${t("eventReplayReadOnly")}</small></span></div><button class="secondary-button action-button" type="button" data-action="event-postflight-replay"><span class="ui-icon icon-play" aria-hidden="true"></span><span>${t("eventsRoundReplay")}</span></button></article></div>`;
  }
  const back = view === "summary" ? "" : `<button class="text-button event-postflight-back" type="button" data-action="event-postflight-summary"><span class="ui-icon icon-chevron-left" aria-hidden="true"></span><span>${t("eventPostFlightBack")}</span></button>`;
  const confirmDisabled = state.eventPostFlightConfirmed || !state.eventPostFlightConsent;
  return `<div class="event-postflight-modal-content"><header class="event-postflight-modal-header"><div><span class="event-card-kicker${canceled ? " is-warning" : ""}"><span class="ui-icon icon-${canceled ? "warning" : "file"}" aria-hidden="true"></span>${t("eventPostFlightTitle")}</span><h2 id="event-postflight-title" tabindex="-1">${canceled ? t("eventCanceledTitle") : t("eventReportTitle")}</h2><p id="event-postflight-modal-copy">${canceled ? t("eventCanceledCopy") : t("eventPostFlightCopy")}</p></div><span class="event-postflight-modal-status"><strong>${t("eventRoundTitle")}</strong><small>${t("eventsRoundClosed")}</small></span></header>${back}${detail}<label class="event-postflight-consent"><input id="event-postflight-consent" type="checkbox"${state.eventPostFlightConsent ? " checked" : ""} /><span><strong>${t("eventPostFlightConsent")}</strong><small>${t("eventPostFlightConsentCopy")}</small></span></label><div class="event-postflight-actions"><button class="secondary-button action-button" type="button" data-action="event-postflight-case"><span class="ui-icon icon-warning" aria-hidden="true"></span><span>${t("eventsRoundCase")}</span></button><button class="primary-button action-button" type="button" data-action="event-postflight-confirm"${confirmDisabled ? " disabled" : ""}><span class="ui-icon icon-check" aria-hidden="true"></span><span>${state.eventPostFlightConfirmed ? t("eventPostFlightConfirmed") : t("eventPostFlightConfirm")}</span></button></div></div>`;
}

function renderParticipatingRoundRow(round) {
  const record = eventsCatalog.find((event) => event.id === round.eventId);
  const team = eventRoundTeam(round);
  const selected = state.eventRoundId === round.id && ["setup", "ack"].includes(state.eventFlow);
  return `<article class="event-round-row${selected ? " is-selected" : ""}"><div class="event-round-row-main"><span class="round-status-dot is-open"></span>${eventTeamIdentityMarkup(record, team, "event-round-identity")}<div><strong>${escapeHtml(`${t(record.titleKey)} · ${t(round.titleKey)}`)}</strong><small>${t("eventsRoundExecutionOpen")} · ${t(round.windowKey)}</small><small>${t("eventsRoundTeam")}: ${escapeHtml(teamDisplayName(team))}</small></div></div><div class="event-row-actions"><button class="primary-button action-button" type="button" data-action="event-open-round" data-event-id="${round.eventId}" data-event-round-id="${round.id}"><span class="ui-icon icon-play" aria-hidden="true"></span><span>${t("eventsRoundParticipate")}</span></button></div></article>`;
}

function renderParticipatingEventRow(entry) {
  const record = entry.record;
  const team = state.teams.find((item) => item.id === entry.teamId) || selectedTeam();
  const nextRound = eventRoundCatalog.find((round) => round.eventId === record.id && (round.open || round.upcoming));
  const withdrawDisabled = !record.enrollmentOpen || state.competitionActive;
  const withdrawTitle = !record.enrollmentOpen ? t("eventsWithdrawParticipationDisabled") : "";
  const withdraw = `<button class="secondary-button action-button" type="button" data-action="event-withdraw-participation" data-event-id="${record.id}"${withdrawDisabled ? ` disabled title="${escapeHtml(withdrawTitle || t("eventsWithdrawParticipationDisabled"))}"` : ""}><span class="ui-icon icon-sign-out" aria-hidden="true"></span><span>${t("eventsWithdrawParticipation")}</span></button>`;
  return `<article class="event-participating-row"><div class="event-participating-main">${eventTeamIdentityMarkup(record, team, "event-participating-identity")}<span class="event-participating-copy"><strong>${t(record.titleKey)}</strong><small>${t("eventsParticipationConfirmed")} · ${t("eventsParticipationTeam")}: ${escapeHtml(teamDisplayName(team))}</small><small>${record.enrollmentOpen ? `${t("eventsParticipationEnrollmentOpen")}: ${t("eventJoinWindowValue")}` : t("eventsParticipationEnrollmentClosed")}</small>${nextRound ? `<small>${t("eventsNextRound")}: ${t(nextRound.titleKey)} · ${t(nextRound.windowKey)}</small>` : ""}</span></div><div class="event-row-actions"><button class="secondary-button action-button" type="button" data-action="event-view-details" data-event-id="${record.id}"><span class="ui-icon icon-eye" aria-hidden="true"></span><span>${t("eventViewDetails")}</span></button>${withdraw}</div></article>`;
}

function renderParticipatingView() {
  if (["setup", "ack"].includes(state.eventFlow)) return `<div class="events-page-subpage event-round-setup-page">${renderParticipationSetup()}</div>`;
  const openRounds = eventRoundCatalog.filter((round) => round.open && eventEnrollmentFor(round.eventId));
  const participations = enrolledEventRecords();
  const openBody = openRounds.length
    ? `<div class="event-participating-list">${openRounds.map(renderParticipatingRoundRow).join("")}</div>`
    : `<div class="event-view-empty event-participating-empty"><span class="ui-icon icon-calendar" aria-hidden="true"></span><strong>${t("eventsNoOpenRounds")}</strong></div>`;
  const eventBody = participations.length
    ? `<div class="event-participating-list">${participations.map(renderParticipatingEventRow).join("")}</div>`
    : `<div class="event-view-empty event-participating-empty"><span class="ui-icon icon-event" aria-hidden="true"></span><strong>${t("eventsNoParticipatingEvents")}</strong></div>`;
  return `<div class="events-participating-page"><section class="event-card event-participating-card" aria-labelledby="events-open-rounds-title"><div class="event-card-heading"><div><h2 id="events-open-rounds-title">${t("eventsOpenRoundsTitle")}</h2><p>${t("eventsOpenRoundsCopy")}</p></div><span class="ui-icon icon-broadcast" aria-hidden="true"></span></div>${openBody}</section><section class="event-card event-participating-card" aria-labelledby="events-participating-events-title"><div class="event-card-heading"><div><h2 id="events-participating-events-title">${t("eventsParticipatingEventsTitle")}</h2><p>${t("eventsParticipatingEventsCopy")}</p></div><span class="ui-icon icon-event" aria-hidden="true"></span></div>${eventBody}</section></div>`;
}

