function renderTeamsPopup() {
  const body = $("#teams-popup-body");
  if (!body) return;
  const team = selectedTeam();
  if (!team) {
    body.innerHTML = `<div class="event-view-empty"><span class="ui-icon icon-person" aria-hidden="true"></span><strong>${t("teamListTitle")}</strong><p>${t("teamNoTeams")}</p></div>`;
    return;
  }
  const teamList = state.teams.map((item) => `<button class="team-popup-list-item${item.id === team.id ? " is-selected" : ""}" type="button" data-action="select-team" data-team-id="${escapeHtml(item.id)}" aria-pressed="${item.id === team.id}">${teamAvatarMarkup(item)}<span><strong>${escapeHtml(teamDisplayName(item))}</strong><small>${item.members}/${item.maxMembers} ${t("eventsTeamMembers")}</small></span></button>`).join("");
  const members = (team.memberKeys || []).map((key) => teamMemberRowMarkup(team, key)).join("");
  body.innerHTML = `<p class="popup-intro">${t("teamPopupIntro")}</p><div class="team-popup-layout"><aside class="team-popup-list"><div class="section-heading"><h3>${t("teamListTitle")}</h3><span class="ui-icon icon-person" aria-hidden="true"></span></div>${teamList}<button class="secondary-button action-button wide-button" type="button" data-action="create-team"><span class="ui-icon icon-add" aria-hidden="true"></span><span>${t("profileCreateTeam")}</span></button></aside><section class="team-popup-editor"><div class="team-popup-identity-heading">${teamAvatarMarkup(team, "team-avatar team-avatar-large")}<div><p class="eyebrow">${t(team.roleKey || "teamRoleMember")}</p><h3>${escapeHtml(teamDisplayName(team))}</h3><p>${team.members}/${team.maxMembers} ${t("eventsTeamMembers")}</p></div></div>${renderTeamIdentityForm(team, { inline: false })}<div class="popup-section"><div class="section-heading"><h3>${t("teamMembersTitle")}</h3><span class="ui-icon icon-person" aria-hidden="true"></span></div><ul class="team-member-list">${members}</ul><div class="event-card-actions"><button class="secondary-button action-button" type="button" data-action="team-invite"><span class="ui-icon icon-add" aria-hidden="true"></span><span>${t("teamInvite")}</span></button></div>${teamMembershipActions(team)}<p class="field-detail">${t("teamInviteCopy")}</p></div></section></div>`;
  if (state.teamEmojiPickerOpen && emojiPickerState.target === "team") renderEmojiPicker();
}

function handleEventImageUpload(file) {
  state.eventImageError = "";
  if (!file) return;
  if (!["image/png", "image/jpeg", "image/webp"].includes(file.type)) {
    state.eventImageError = t("eventsCompetitionImageError");
    renderEventImagePopup();
    return;
  }
  const objectUrl = globalThis.URL?.createObjectURL?.(file);
  if (!objectUrl || typeof globalThis.Image !== "function") {
    state.eventImageError = t("eventsCompetitionImageError");
    renderEventImagePopup();
    return;
  }
  const probe = new Image();
  probe.onload = () => {
    if (!probe.naturalWidth || !probe.naturalHeight) {
      state.eventImageError = t("eventsCompetitionImageError");
      URL.revokeObjectURL(objectUrl);
    } else state.eventImageDraft = { url: objectUrl, fileName: file.name, crop: "1:1", width: 256, height: 256 };
    renderEventImagePopup();
  };
  probe.onerror = () => {
    state.eventImageError = t("eventsCompetitionImageError");
    URL.revokeObjectURL(objectUrl);
    renderEventImagePopup();
  };
  probe.src = objectUrl;
}

async function handleEventAdminArenaUpload(file, roundIndex) {
  if (!file || !state.eventAdminDraft) return;
  const extension = String(file.name || "").split(".").pop().toLowerCase();
  if (!["arena", "json"].includes(extension)) {
    state.eventAdminError = t("eventsAdminArenaImportError");
    renderEventsPage();
    return;
  }
  let fileHash = "";
  try {
    const bytes = await file.arrayBuffer();
    if (!bytes.byteLength) throw new Error("Arena file is empty");
    const digest = await globalThis.crypto?.subtle?.digest("SHA-256", bytes);
    if (!digest) throw new Error("Arena file hashing is unavailable");
    fileHash = [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
  } catch {
    state.eventAdminError = t("eventsAdminArenaImportError");
    renderEventsPage();
    return;
  }
  if (!state.eventAdminDraft) return;
  syncEventAdminDraftFromDom();
  const round = state.eventAdminDraft.rounds[Number(roundIndex)];
  if (!round) return;
  if ((round.arenaOptions || []).length >= 5) {
    state.eventAdminError = t("eventsAdminArenaLimitError");
    renderEventsPage();
    return;
  }
  const baseName = String(file.name || "").replace(/\.(arena|json)$/i, "").trim() || t("eventsAdminArenaImported");
  const uploadId = `event-file-${state.eventAdminArenaUploadCounter++}`;
  round.arenaOptions.push({
    id: `uploaded-${uploadId}`,
    name: baseName,
    source: "file",
    fileName: file.name,
    fileBytes: Number(file.size) || 0,
    fileFormat: extension,
    snapshotId: `arena:${uploadId}@1`,
    compiledPathSha256: `sha256:${fileHash}`,
    generationKey: "eventsAdminArenaImported",
    selected: true
  });
  state.eventAdminDirty = true;
  state.eventAdminError = "";
  renderEventsPage();
}

async function handleEventAdminTeamCsvUpload(file) {
  if (!file || !state.eventAdminDraft) return;
  const isCsv = String(file.name || "").toLowerCase().endsWith(".csv") || file.type === "text/csv";
  if (!isCsv) {
    state.eventAdminTeamError = t("eventsAdminTeamCsvError");
    state.eventAdminTeamCsvStatus = "";
    renderEventsPage();
    return;
  }
  let contents = "";
  try {
    contents = await file.text();
  } catch {
    state.eventAdminTeamError = t("eventsAdminTeamCsvError");
    state.eventAdminTeamCsvStatus = "";
    renderEventsPage();
    return;
  }
  syncEventAdminDraftFromDom();
  const parsed = parseEventAdminTeamCsv(contents);
  if (parsed.error) {
    state.eventAdminTeamError = parsed.error;
    state.eventAdminTeamCsvStatus = "";
    renderEventsPage();
    return;
  }
  state.eventAdminTeamRoster.push(...parsed.teams);
  state.eventAdminTeamError = "";
  state.eventAdminTeamCsvStatus = `${parsed.teams.length} ${t("eventsAdminTeamCsvImported")}.`;
  state.eventAdminDirty = true;
  renderEventsPage();
  showToast("toastEventAdminTeamImported");
}

