function renderEventHistoryReport() {
  const record = eventHistoryRecords().find((item) => item.id === state.eventHistoryReportId) || eventHistoryRecords()[0];
  const event = eventsCatalog.find((item) => item.id === record.eventId);
  const team = state.teams.find((item) => item.id === record.teamId);
  const report = record.report;
  const log = report.log.map(([time, key]) => `<li><time>${time}</time><span><strong>${t(key)}</strong><small>${t(record.titleKey)}</small></span></li>`).join("");
  return `<div class="events-page-subpage event-history-report-page"><header class="event-subpage-header"><button class="text-button" type="button" data-action="event-history-report-back"><span class="ui-icon icon-chevron-left" aria-hidden="true"></span><span>${t("eventsHistoryReportBack")}</span></button><div class="event-subpage-title"><h2 id="events-page-title">${t("eventsHistoryReportTitle")}</h2><p>${t(record.titleKey)} · ${team ? escapeHtml(teamDisplayName(team)) : t("eventTeam")}</p></div><span class="ui-icon icon-file" aria-hidden="true"></span></header><section class="event-card event-history-report-summary"><div class="event-history-report-identity">${eventTeamIdentityMarkup(event, team, "event-history-report-identity-stack")}<div><h3>${t(record.titleKey)}</h3><p>${t(record.metaKey)}</p></div></div><p>${t("eventsHistoryReportCopy")}</p><div class="event-history-report-metrics"><div><span>${t("eventsHistoryReportScore")}</span><strong>${t(report.scoreKey)}</strong></div><div><span>${t("eventsHistoryReportDuration")}</span><strong>${t(report.durationKey)}</strong></div><div><span>${t("eventsHistoryReportRobot")}</span><strong>${escapeHtml(report.robot)}</strong></div><div><span>${t("eventsHistoryReportProgram")}</span><strong>${t(report.programKey)}</strong></div></div></section><section class="event-card event-history-log-card"><div class="event-card-heading"><div><h3>${t("eventsHistoryReportLogTitle")}</h3><p>${t("eventsHistoryReportLogCopy")}</p></div><span class="ui-icon icon-route" aria-hidden="true"></span></div><ol class="event-history-log">${log}</ol><div class="event-card-actions">${eventHistoryReportLogActions(record)}<button class="secondary-button action-button" type="button" data-action="event-open-replay" data-event-replay-id="${record.replayId}"><span class="ui-icon icon-history" aria-hidden="true"></span><span>${t("eventsHistoryReplay")}</span></button>${renderEventHistoryContestAction(record)}</div></section></div>`;
}

function renderHistoryPage() {
  if (state.eventHistoryReportId) return renderEventHistoryReport();
  const rounds = eventHistoryRecords();
  return `<div class="events-page-subpage"><header class="event-subpage-header"><div><h2 id="events-page-title">${t("eventsHistoryPageTitle")}</h2><p>${t("eventsHistoryPageCopy")}</p></div><span class="ui-icon icon-history" aria-hidden="true"></span></header><section class="event-card event-history-card"><div class="event-history-list">${rounds.map((round) => { const team = state.teams.find((item) => item.id === round.teamId); const event = eventsCatalog.find((item) => item.id === round.eventId); return `<article class="event-history-row"><div class="event-history-row-copy">${eventTeamIdentityMarkup(event, team, "event-history-identity")}<span><strong>${t(round.titleKey)}</strong><small>${t(round.metaKey)}</small></span></div><div class="event-row-actions"><button class="secondary-button action-button" type="button" data-action="event-history-report" data-event-history-report-id="${round.id}"><span class="ui-icon icon-file" aria-hidden="true"></span><span>${t("eventsHistoryReport")}</span></button><button class="secondary-button action-button" type="button" data-action="event-open-replay" data-event-replay-id="${round.replayId}"><span class="ui-icon icon-play" aria-hidden="true"></span><span>${t("eventsHistoryReplay")}</span></button>${renderEventHistoryContestAction(round)}</div></article>`; }).join("")}</div></section></div>`;
}

