  footer.innerHTML = `<button class="secondary-button action-button" type="button" data-close-popup="team-invite"><span class="ui-icon icon-close" aria-hidden="true"></span><span>${t("cancelButton")}</span></button>${state.eventInviteSent ? `<button class="primary-button action-button" type="button" data-close-popup="team-invite"><span class="ui-icon icon-check" aria-hidden="true"></span><span>${t("doneButton")}</span></button>` : `<button class="primary-button action-button" type="button" data-action="send-team-invite"><span class="ui-icon icon-add" aria-hidden="true"></span><span>${t("teamInviteSend")}</span></button>`}`;
