function moveDiagnosticRobot(direction, { continuous = false } = {}) {
  if (!simulatorRobotReady() || !state.simulationRuntime || state.competitionActive) return;
  if (state.section === "simulator" && state.simulationRuntimeFrame === null) startSimulationRuntimeLoop();
  const resolvedDirection = { left: "right", right: "left" }[direction] || direction;
  if (!state.routineOpen) {
    const snapshot = state.simulationRuntime.commandWhileStopped(resolvedDirection, state.manualRobotSpeed, { persistent: continuous });
    state.simulationSpawnOverride = cloneArenaValue(snapshot.robot);
    applySimulationRuntimeSnapshot(snapshot);
    return;
  }
 if (state.simulationRuntime && state.routineOpen && !state.competitionActive) {
    applySimulationRuntimeSnapshot(state.simulationRuntime.command(resolvedDirection, state.manualRobotSpeed, { persistent: continuous }));
    return;
  }
  const amount = state.manualRobotSpeed;
  const position = state.manualRobotPosition;
  if (direction === "forward") position.z = Math.max(-4, position.z - amount);
  if (direction === "back") position.z = Math.min(4, position.z + amount);
  if (direction === "left") position.yaw = (position.yaw + 345) % 360;
  if (direction === "right") position.yaw = (position.yaw + 15) % 360;
  updateDiagnosticsMovementUI();
}

function releaseDiagnosticRobot() {
  if (!state.simulationRuntime || state.competitionActive || state.openPopup !== "diagnostics") return;
  const snapshot = state.simulationRuntime.releaseManualCommand?.() || state.simulationRuntime.snapshot();
  if (!state.routineOpen && ["idle", "stopped"].includes(snapshot.status)) state.simulationSpawnOverride = cloneArenaValue(snapshot.robot);
  applySimulationRuntimeSnapshot(snapshot);
}

function startDiagnosticsDpadHold(event) {
  const button = event.target.closest?.(".diagnostics-dpad-button");
  if (!button || button.disabled || state.openPopup !== "diagnostics") return;
  event.preventDefault();
  state.diagnosticsManualPointerId = event.pointerId;
  state.diagnosticsManualPointerStartedAt = globalThis.performance?.now?.() || Date.now();
  state.diagnosticsManualPointerDirection = button.dataset.direction || "";
  state.diagnosticsDpadSuppressClick = true;
  button.setPointerCapture?.(event.pointerId);
  moveDiagnosticRobot(button.dataset.direction, { continuous: true });
}

function stopDiagnosticsDpadHold(event) {
  if (state.diagnosticsManualPointerId !== event.pointerId) return;
  const direction = state.diagnosticsManualPointerDirection;
  const heldMs = (globalThis.performance?.now?.() || Date.now()) - state.diagnosticsManualPointerStartedAt;
  const quickTap = event.type === "pointerup" && heldMs <= ROBOT_MANUAL_CONTROL_PROFILE.tapStepSeconds * 1000;
  state.diagnosticsManualPointerId = null;
  state.diagnosticsManualPointerStartedAt = 0;
  state.diagnosticsManualPointerDirection = "";
  if (event.type === "pointercancel") state.diagnosticsDpadSuppressClick = false;
  releaseDiagnosticRobot();
  if (quickTap && direction && state.openPopup === "diagnostics" && !state.competitionActive) moveDiagnosticRobot(direction);
}

function updateDiagnosticsSelectionUI() {
  const diagnosticsOpen = state.diagnostics && state.openPopup === "diagnostics" && diagnosticsRoutineOptionEnabled();
  $$(".sim-diagnostics-component").forEach((button) => {
    const selected = diagnosticsOpen && state.diagnosticsComponents.includes(button.dataset.diagnosticsComponent);
    button.classList.toggle("is-selected", selected);
    button.setAttribute("aria-pressed", String(selected));
  });
}

function toggleDiagnosticsComponentSelection(componentId) {
  if (!diagnosticsRoutineOptionEnabled()) return;
  const wasSelected = state.diagnosticsComponents.includes(componentId);
  if (wasSelected) {
    state.diagnosticsComponents = state.diagnosticsComponents.filter((id) => id !== componentId);
    if (state.diagnosticsActiveComponentId === componentId || !state.diagnosticsComponents.includes(state.diagnosticsActiveComponentId)) {
      state.diagnosticsActiveComponentId = state.diagnosticsComponents[0] || "";
    }
  } else {
    state.diagnosticsComponents = [componentId, ...state.diagnosticsComponents];
    state.diagnosticsActiveComponentId = componentId;
  }
  state.simulationSelection = state.diagnosticsComponents.includes(componentId)
    ? `sim-${componentId}`
    : state.diagnosticsComponents[0] ? `sim-${state.diagnosticsComponents[0]}` : "";
  state.diagnostics = true;
  updateDiagnosticsSelectionUI();
}

function setActiveDiagnosticsComponent(componentId, { restoreFocus = false } = {}) {
  if (!state.diagnosticsComponents.includes(componentId)) return;
  state.diagnosticsActiveComponentId = componentId;
  renderDiagnosticsPopup();
  if (restoreFocus) requestAnimationFrame(() => {
    const tab = [...($("#diagnostics-popup-body")?.querySelectorAll("[data-diagnostics-component-tab]") || [])]
      .find((button) => button.dataset.diagnosticsComponentTab === componentId);
    tab?.focus();
  });
}

function deselectDiagnosticsComponent(componentId) {
  if (!state.diagnosticsComponents.includes(componentId)) return;
  toggleDiagnosticsComponentSelection(componentId);
  renderStage();
  renderDiagnosticsPopup();
  requestAnimationFrame(() => {
    const body = $("#diagnostics-popup-body");
    const nextTab = body?.querySelector('.diagnostics-selected-tabs [role="tab"][aria-selected="true"]');
    (nextTab || body?.querySelector('[data-action="toggle-diagnostics-component-picker"]'))?.focus();
  });
}

function stopDiagnosticsFrameRead() {
  if (state.diagnosticsFrameHandle !== null && globalThis.cancelAnimationFrame) globalThis.cancelAnimationFrame(state.diagnosticsFrameHandle);
  state.diagnosticsFrameHandle = null;
  globalThis.sboticsSimulationStage?.releaseSensorCaptureTargets?.();
}

function updateDiagnosticsFrame() {
  if (!state.diagnostics || state.openPopup !== "diagnostics" || !diagnosticsRoutineOptionEnabled() || !state.diagnosticsComponents.length) {
    state.diagnosticsFrameHandle = null;
    return;
  }
  state.diagnosticsFrame += 1;
  const stage = activeSpatialStage();
  state.diagnosticsComponents.forEach((componentId) => {
    const component = diagnosticsComponentById(componentId);
    if (component?.typeId === "colorSensor" || component?.typeId === "wedgeColorSensor") {
      const sample = stage?.sampleRobotColorSensor?.(componentId);
      if (sample) state.diagnosticsSensorReadings[componentId] = sample;
    }
    if (component?.typeId === "camera") {
      const frame = stage?.captureRobotCameraFrame?.(componentId);
      const canvas = document.querySelector(`[data-diagnostics-camera-preview="${CSS.escape(componentId)}"]`);
      const status = document.querySelector(`[data-diagnostics-camera-status="${CSS.escape(componentId)}"]`);
      if (frame && canvas) {
        state.diagnosticsSensorReadings[componentId] = { frame: frame.frame, width: frame.width, height: frame.height, live: true };
        const context = canvas.getContext("2d", { alpha: false });
        if (context) {
          const image = context.createImageData(frame.width, frame.height);
          for (let y = 0; y < frame.height; y += 1) {
            const sourceY = frame.height - 1 - y;
            for (let x = 0; x < frame.width; x += 1) {
              const sourceIndex = (sourceY * frame.width + x) * 4;
              const targetIndex = (y * frame.width + x) * 4;
              image.data[targetIndex] = frame.pixels[sourceIndex];
              image.data[targetIndex + 1] = frame.pixels[sourceIndex + 1];
              image.data[targetIndex + 2] = frame.pixels[sourceIndex + 2];
              image.data[targetIndex + 3] = 255;
            }
          }
          context.putImageData(image, 0, 0);
          if (status) status.textContent = `${frame.width} × ${frame.height} · ${t("diagnosticsCameraLive")}`;
        }
      } else if (!canvas && status) status.textContent = t("diagnosticsCameraWaiting");
    }
    if (component?.typeId === "colorSensor" || component?.typeId === "wedgeColorSensor") updateDiagnosticsColorReading(componentId);
    else diagnosticsReadingRows(componentId).forEach(([, , value], index) => {
      const target = document.querySelector(`[data-diagnostics-reading-component="${componentId}"][data-diagnostics-reading-index="${index}"]`);
      if (target) target.textContent = value;
    });
    document.querySelectorAll(`[data-diagnostics-state-component="${CSS.escape(componentId)}"]`).forEach((checkbox) => {
      checkbox.checked = diagnosticsComponentReadings(componentId)[checkbox.dataset.diagnosticsStateKey] === true;
    });
  });
  state.diagnosticsFrameHandle = globalThis.requestAnimationFrame?.(updateDiagnosticsFrame) ?? null;
}

function startDiagnosticsFrameRead() {
  if (state.diagnosticsFrameHandle === null && diagnosticsRoutineOptionEnabled() && state.diagnosticsComponents.length && globalThis.requestAnimationFrame) {
    state.diagnosticsFrameHandle = globalThis.requestAnimationFrame(updateDiagnosticsFrame);
  }
}

