    return `<button class="robot-scene-part-item${selected ? " is-selected" : ""}" type="button" role="option" aria-selected="${selected}" aria-label="${escapeHtml(`${robotScenePartLabel(part)} · ${t(part.typeKey)}`)}" data-action="select-robot-component" data-component="${escapeHtml(part.instanceId)}">${robotPartThumbnailMarkup(part, "is-34")}<span class="robot-scene-part-copy"><strong>${escapeHtml(robotScenePartLabel(part))}</strong><small>${escapeHtml(t(part.typeKey))}</small></span><span class="ui-icon icon-${selected ? "check" : "chevron-right"}" aria-hidden="true"></span></button>`;
