  if (draft.type === "box" && field !== "position") return;
  if (field === "position" && draft.positionRandom === true && ["x", "z"].includes(axis)) return;
  const step = Number(state.arenaObjectTransformSteps[field]) || arenaObjectTransformStepOptions[field][0];
  const current = Number(draft[field]?.[axis]) || 0;
  draft[field] = { ...(draft[field] || {}), [axis]: normalizeArenaNumber(current + (Number(direction) < 0 ? -step : step)) };
